def _protect_audit_log() -> None:
    """С-18: записи журнала аудита недоступны для изменения — UPDATE и DELETE запрещены на уровне СУБД."""
    if op.get_bind().dialect.name == "postgresql":
        op.execute(
            "CREATE OR REPLACE FUNCTION audit_log_readonly() RETURNS trigger AS $$ BEGIN "
            "RAISE EXCEPTION 'Записи журнала аудита изменять нельзя'; END; $$ LANGUAGE plpgsql")
        op.execute("CREATE TRIGGER audit_log_no_update BEFORE UPDATE OR DELETE ON audit_log "
                   "FOR EACH ROW EXECUTE FUNCTION audit_log_readonly()")
    else:
        for event in ("UPDATE", "DELETE"):
            op.execute(f"CREATE TRIGGER audit_log_no_{event.lower()} BEFORE {event} ON audit_log "
                       "BEGIN SELECT RAISE(ABORT, 'Записи журнала аудита изменять нельзя'); END")


